mapper.update:
update tbl_question
	set content = #{content}, question_type = #{questionType}, required = #{required}, sort_order = #{sortOrder}
		where question_seq = #{questionSeq}

update tbl_question_option
	set content = #{content}, sort_order = #{sortOrder}, enabled = #{enabled}
		where option_seq = #{optionSeq} and question_seq = #{questionSeq}
